def _validate_define_site_geo(body: dict[str, Any]) -> str | None:
    """defineDeploymentSite.geo is a GeoJSON Feature (lexicon-declared as
    string). Accept either a JSON-string OR a pre-parsed object.
    """
    geo = body.get("geo")
    if geo is None:
        return None
    if isinstance(geo, dict):
        return None
    if isinstance(geo, str):
        try:
            json.loads(geo)
        except json.JSONDecodeError as exc:
            return f"InvalidGeoJSON: {exc}"
        return None
    return "InvalidGeoJSON: geo must be a JSON string or object"

def _parse_iso_to_epoch(iso: str) -> float:
    """Parse an ISO-8601 datetime to epoch seconds, tolerant of missing TZ."""
    if not iso:
        return 0.0
    fmts = ("%Y-%m-%dT%H:%M:%SZ", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d")
    for fmt in fmts:
        try:
            return time.mktime(time.strptime(iso[: len(fmt) + 4], fmt))
        except (ValueError, TypeError):
            continue
    return 0.0

