def extract_features_node(state: dict[str, Any]) -> dict[str, Any]:
    """POST text to the configured model and receive its hidden-state vector representation. Used by mst-projector embedders. The API key is supplied via Authorization: Bearer <key> by the caller and is NOT part of this lexicon — yorishiri never store credentials."""
    params = dict(state.get("params") or {})
    body = state.get("body") or None
    path = "/pipeline/feature-extraction/{model_id}"
    for key in list(params.keys()):
        token = "{" + key + "}"
        if token in path:
            path = path.replace(token, str(params.pop(key)))
    url = f"{YORISHIRO_BASE_URL}{path}"
    status, text = _http_call("POST", url, params, body if isinstance(body, dict) and body else None)
    out: dict[str, Any] = {**state, "http_status": status}
    if status == 0:
        out["error"] = text
        return out
    if status >= 400:
        out["error"] = text[:1000]
        out["body_raw"] = text
        return out
    if "application/json" == "application/json":
        parsed = _attempt_json(text)
        if parsed is not None:
            out["json"] = parsed
            return out
    out["body_raw"] = text
    return out

