def _charter_rider_scan(text: str) -> tuple[bool, str]:
    """Delegates to the canonical §2(a)..(h) scanner in
    `etzhayyim_organism.sensors.charter_rider` (per ADR-2605192200 v2.0).
    The import is lazy so a missing organism dep doesn't break import
    of validate.py at module load time."""
    try:
        from etzhayyim_organism.sensors.charter_rider import scan  # type: ignore
    except ImportError:
        # Fall-back: only the smallest sane subset to keep the loop functional
        # in environments where etzhayyim-organism is not on the path.
        lower = text.lower()
        for term in ("buy now", "limited offer", "discount code",
                     "affiliate link", "promo code"):
            if term in lower:
                return False, f"§2(c) (fallback) advertising term: {term!r}"
        return True, "ok (fallback scanner — install etzhayyim-organism for full coverage)"

    r = scan(text)
    return r.ok, r.reason()

def _parse_qwen_chat_text(text: str) -> tuple[str | None, str | None]:
    """Parse Qwen `<|im_start|>role\n...<|im_end|>` envelope, return (last_user, last_assistant)."""
    last_user: str | None = None
    last_assistant: str | None = None
    for m in _QWEN_TURN_RX.finditer(text):
        role, content = m.group(1), m.group(2).strip()
        if role == "user":
            last_user = content
        elif role == "assistant" and last_user is not None:
            last_assistant = content
    return last_user, last_assistant

def _stream_hf(name: str, cap: int, fmt: str = "auto"):
    """Stream (prompt, response) tuples from a HF dataset.

    fmt:
      - "auto"      try prompt/instruction/question + response/output/answer (default)
      - "qwen-text" single `text` column with Qwen chat envelope (Opus reasoning corpus)
      - "messages"  `messages` list of {role, content}
    """
    from datasets import load_dataset  # type: ignore
    ds = load_dataset(name, split="train", streaming=True)
    seen = 0
    for row in ds:
        if fmt == "qwen-text":
            prompt, response = _parse_qwen_chat_text(row.get("text", "") or "")
        elif fmt == "messages":
            msgs = row.get("messages") or []
            last_u, last_a = None, None
            for m in msgs:
                if m.get("role") == "user":
                    last_u = m.get("content")
                elif m.get("role") == "assistant" and last_u is not None:
                    last_a = m.get("content")
            prompt, response = last_u, last_a
        else:
            prompt = row.get("prompt") or row.get("instruction") or row.get("question")
            response = row.get("response") or row.get("output") or row.get("answer")
        yield prompt, response
        seen += 1
        if seen >= cap * 2:  # over-yield; caller caps
            break

def _resolve_targets(model, student_id: str) -> list[str]:
    """Inspect the model and return LoRA target_modules appropriate for its arch.

    Most HF models expose `q_proj/k_proj/v_proj/o_proj` as plain nn.Linear. Gemma 4 wraps
    them in `Gemma4ClippableLinear`, so we must target the inner `.linear` submodule.
    """
    import torch.nn as nn
    has_wrapper = False
    for name, mod in model.named_modules():
        if name.endswith(".q_proj") and not isinstance(mod, nn.Linear):
            inner_linear = any(
                isinstance(sub, nn.Linear) for sub in mod.modules()
            )
            if inner_linear:
                has_wrapper = True
            break
    if has_wrapper:
        return ["q_proj.linear", "k_proj.linear", "v_proj.linear", "o_proj.linear"]
    return ["q_proj", "k_proj", "v_proj", "o_proj"]

def _resolve_collections(collections: list[str] | str | None) -> list[str] | None:
    """Normalize collections arg. None → all collections (no filter)."""
    if collections is None:
        return None
    if isinstance(collections, str):
        return [collections]
    return list(collections)

def _parse_op_path(path: str) -> tuple[str, str]:
    """Pure: split AT op path 'collection/rkey' → (collection, rkey).

    Returns ('', '') on malformed paths.
    """
    if "/" not in path:
        return ("", "")
    collection, _, rkey = path.partition("/")
    return (collection, rkey)

def _data_dir() -> str:
    """LanceDB storage root.

    Defaults to /data/mst-projector/ in production, or
    ETZHAYYIM_MST_PROJECTOR_DATA_DIR env override for tests.
    """
    return os.environ.get("ETZHAYYIM_MST_PROJECTOR_DATA_DIR", _DEFAULT_DATA_DIR)

def _flatten_record(record: dict[str, Any]) -> dict[str, Any]:
    """Flatten a record dict for LanceDB columnar storage.

    Top-level scalars (str, int, float, bool, None) stay typed.
    Nested dicts/lists are JSON-stringified into str columns.

    Args:
        record: Decoded AT Protocol record value dict.

    Returns:
        Flat dict ready for LanceDB row insertion.
    """
    flat: dict[str, Any] = {}
    for k, v in record.items():
        if isinstance(v, (str, int, float, bool)) or v is None:
            flat[k] = v
        else:
            flat[k] = json.dumps(v, ensure_ascii=False)
    return flat

def get_indexer() -> Indexer:
    """Return the module-level singleton Indexer, creating it on first call."""
    global _singleton
    if _singleton is None:
        _singleton = Indexer()
    return _singleton

async def _query_by_collection(request: web.Request) -> web.Response:
    """POST /xrpc/com.etzhayyim.mstProjector.queryByCollection

    Input:  collection: str, limit: int=50, cursor: str?
    Output: records: list, cursor: str?
    """
    try:
        body = await request.json()
    except Exception:
        return web.json_response(
            {"error": "InvalidRequest", "message": "body must be JSON"},
            status=400,
        )

    collection = body.get("collection")
    if not collection:
        return web.json_response(
            {"error": "InvalidRequest", "message": "collection required"},
            status=400,
        )

    try:
        limit = int(body.get("limit", 50))
        if limit < 1 or limit > 1000:
            raise ValueError("out of range")
    except (ValueError, TypeError):
        return web.json_response(
            {"error": "InvalidRequest", "message": "limit must be 1–1000"},
            status=400,
        )

    # Cursor is opaque offset-based: cursor value = string representation of int offset
    cursor = body.get("cursor")
    try:
        offset = int(cursor) if cursor is not None else 0
        if offset < 0:
            raise ValueError
    except (ValueError, TypeError):
        return web.json_response(
            {"error": "InvalidRequest", "message": "invalid cursor"},
            status=400,
        )

    indexer = get_indexer()
    # Fetch offset+limit+1 rows to detect whether a next page exists
    all_records = await indexer.query(
        collection=collection,
        limit=offset + limit + 1,
    )
    page = all_records[offset : offset + limit + 1]

    next_cursor: str | None = None
    if len(page) > limit:
        page = page[:limit]
        next_cursor = str(offset + limit)

    return web.json_response({"records": page, "cursor": next_cursor})

async def _query_by_did(request: web.Request) -> web.Response:
    """POST /xrpc/com.etzhayyim.mstProjector.queryByDid

    Input:  did: str, collection?: str, limit: int=50, cursor?: str
    Output: records: list, cursor: str?
    """
    try:
        body = await request.json()
    except Exception:
        return web.json_response(
            {"error": "InvalidRequest", "message": "body must be JSON"},
            status=400,
        )

    did = body.get("did")
    if not did:
        return web.json_response(
            {"error": "InvalidRequest", "message": "did required"},
            status=400,
        )

    collection = body.get("collection")

    try:
        limit = int(body.get("limit", 50))
        if limit < 1 or limit > 1000:
            raise ValueError("out of range")
    except (ValueError, TypeError):
        return web.json_response(
            {"error": "InvalidRequest", "message": "limit must be 1–1000"},
            status=400,
        )

    cursor = body.get("cursor")
    try:
        offset = int(cursor) if cursor is not None else 0
        if offset < 0:
            raise ValueError
    except (ValueError, TypeError):
        return web.json_response(
            {"error": "InvalidRequest", "message": "invalid cursor"},
            status=400,
        )

    # Escape single quotes in DID value (DIDs should not contain them, but be safe)
    safe_did = did.replace("'", "''")
    filter_sql = f"did = '{safe_did}'"

    indexer = get_indexer()

    if collection:
        all_records = await indexer.query(
            collection=collection,
            filter_sql=filter_sql,
            limit=offset + limit + 1,
        )
    else:
        # Cross-collection slow path — enumerate all tables
        collections = await indexer.list_collections()
        gathered: list[dict[str, Any]] = []
        for col in collections:
            try:
                col_records = await indexer.query(
                    collection=col,
                    filter_sql=filter_sql,
                    limit=limit,
                )
                gathered.extend(col_records)
            except Exception as exc:
                _log.warning("query_by_did: skip collection %s: %s", col, exc)
        all_records = gathered[: offset + limit + 1]

    page = all_records[offset : offset + limit + 1]

    next_cursor: str | None = None
    if len(page) > limit:
        page = page[:limit]
        next_cursor = str(offset + limit)

    return web.json_response({"records": page, "cursor": next_cursor})

async def _query_by_field(request: web.Request) -> web.Response:
    """POST /xrpc/com.etzhayyim.mstProjector.queryByField

    Input:  collection: str, fieldName: str, fieldValue: str, limit: int=50
    Output: records: list
    """
    try:
        body = await request.json()
    except Exception:
        return web.json_response(
            {"error": "InvalidRequest", "message": "body must be JSON"},
            status=400,
        )

    collection = body.get("collection")
    # Accept both camelCase (wire) and snake_case (internal)
    field_name = body.get("fieldName") or body.get("field_name")
    field_value = body.get("fieldValue") if "fieldValue" in body else body.get("field_value")

    if not collection or not field_name or field_value is None:
        return web.json_response(
            {
                "error": "InvalidRequest",
                "message": "collection, fieldName, fieldValue required",
            },
            status=400,
        )

    # SQL injection defence: reject field names that don't match safe pattern
    if not _SAFE_FIELD_RE.match(field_name):
        return web.json_response(
            {
                "error": "InvalidRequest",
                "message": (
                    "fieldName must start with a letter or underscore and "
                    "contain only alphanumeric characters and underscores"
                ),
            },
            status=400,
        )

    try:
        limit = int(body.get("limit", 50))
        if limit < 1 or limit > 1000:
            raise ValueError("out of range")
    except (ValueError, TypeError):
        return web.json_response(
            {"error": "InvalidRequest", "message": "limit must be 1–1000"},
            status=400,
        )

    # Escape single quotes in the value to prevent SQL injection
    safe_value = str(field_value).replace("'", "''")

    indexer = get_indexer()
    try:
        records = await indexer.query(
            collection=collection,
            filter_sql=f"{field_name} = '{safe_value}'",
            limit=limit,
        )
    except Exception as exc:
        _log.warning("query_by_field: query failed: %s", exc)
        return web.json_response(
            {"error": "UnindexedField", "message": str(exc)},
            status=400,
        )

    return web.json_response({"records": records})

async def _healthz(request: web.Request) -> web.Response:
    """Liveness + readiness probe.

    Returns 200 with summary if indexer + subscriber are healthy.
    Returns 503 if either is unreachable.
    """
    indexer = get_indexer()
    try:
        collections = await indexer.list_collections()
        return web.json_response({
            "ok": True,
            "service": "mst-projector",
            "indexed_collections": len(collections),
            "data_dir": str(indexer.data_dir),
        })
    except Exception as e:
        return web.json_response({
            "ok": False,
            "service": "mst-projector",
            "error": str(e),
        }, status=503)

async def _count_by_collection(request: web.Request) -> web.Response:
    """POST /xrpc/com.etzhayyim.mstProjector.countByCollection

    Input:  collection: str, asOf?: str (ignored — reserved for future)
    Output: count: int, asOf: str
    """
    try:
        body = await request.json()
    except Exception:
        return web.json_response(
            {"error": "InvalidRequest", "message": "body must be JSON"},
            status=400,
        )

    collection = body.get("collection")
    if not collection:
        return web.json_response(
            {"error": "InvalidRequest", "message": "collection required"},
            status=400,
        )

    indexer = get_indexer()
    # M4 optimisation: use LanceDB native count_rows() if available (O(1) on
    # compacted tables) — avoids full 100k-row scan from M3 implementation.
    # Fallback to query-based count if count_rows raises (e.g. very old LanceDB).
    as_of = datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")
    try:
        count = await indexer.count_rows(collection)
    except Exception as exc:
        _log.warning(
            "count_by_collection: count_rows failed (%s), falling back to scan", exc
        )
        records = await indexer.query(collection=collection, limit=100_000)
        count = len(records)

    return web.json_response({"count": count, "asOf": as_of})
